import sys
from collections import deque

def is_valid(x, y, h, w):
    return 0 <= x < h and 0 <= y < w

def bfs(grid, visited, x, y, h, w):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(x, y)])
    visited[x][y] = True
    component = []

    while queue:
        cx, cy = queue.popleft()
        component.append((cx, cy))

        for dx, dy in directions:
            nx, ny = cx + dx, cy + dy
            if is_valid(nx, ny, h, w) and grid[nx][ny] == 'X' and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))

    return component

def can_partition(grid, h, w, k):
    visited = [[False] * w for _ in range(h)]
    components = []

    for i in range(h):
        for j in range(w):
            if grid[i][j] == 'X' and not visited[i][j]:
                component = bfs(grid, visited, i, j, h, w)
                components.append(component)

    total_area = sum(len(c) for c in components)
    if total_area % k != 0:
        return False

    target_size = total_area // k
    components.sort(key=len, reverse=True)

    def backtrack(index, current_pieces):
        if index == len(components):
            return True

        for piece in current_pieces:
            if len(piece) + len(components[index]) > target_size:
                continue

            piece.extend(components[index])
            if backtrack(index + 1, current_pieces):
                return True
            piece.pop()

        return False

    initial_pieces = [[] for _ in range(k)]
    return backtrack(0, initial_pieces)

