def bfs(grid, h, w, start):
    queue = deque([start])
    visited = set([start])
    component = []

    while queue:
        x, y = queue.popleft()
        component.append((x, y))

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 'X' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return component

def find_components(grid, h, w):
    components = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 'X':
                component = bfs(grid, h, w, (i, j))
                components.append(component)
    return components

