    total_squares = sum(len(comp) for comp in components)
    for k in range(2, 6):
        if total_squares % k == 0:
            part_size = total_squares // k
            if all(len(comp) == part_size for comp in components):
                return True
    return False

def label_polyomino(grid, components, h, w):
